        after=rf.primary_snapshot()
        if before['mainVhostSha256']!=after['mainVhostSha256'] or before['api']['commit']!=after['api']['commit']:raise RuntimeError('Primary drift')
        a=datetime.fromisoformat(before['api']['startedAt'].replace('Z','+00:00'));b=datetime.fromisoformat(after['api']['startedAt'].replace('Z','+00:00'))
        if abs((a-b).total_seconds())>2:raise RuntimeError('API restart')
        result.update(status='PASS',primaryUnchanged=True)
        installed=json.loads((ROOT/'installed.json').read_text());installed['vhostSha256']=result['vhostSha256'];(ROOT/'installed.json').write_text(json.dumps(installed,indent=2))
